export function scopeGround(x,z,base){
if(Math.abs(x)<=220&&Math.abs(z)<=220)return base;
const {x0,z0,step,nx,nz,heights,weights}=grid;const gx=(x-x0)/step,gz=(z-z0)/step;if(gx<0||gz<0||gx>=nx-1||gz>=nz-1)return base;
const i=Math.floor(gx),j=Math.floor(gz),u=gx-i,v=gz-j,k=j*nx+i;
const sample=a=>(a[k]*(1-u)+a[k+1]*u)*(1-v)+(a[k+nx]*(1-u)+a[k+nx+1]*u)*v;
const w=sample(weights);return base*(1-w)+sample(heights)*w;
}
